{
  "status": "SUPPORTED",
  "task_summary": "Prepare refreshment settings for two people near seating areas and move the entertainment control to an accessible location.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds refreshments for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["table", "surface", "desk"]
    ,
      "required_properties": ["stable", "flat"]
    }
  ,
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["remote", "controller"]
    ,
      "required_properties": ["buttons", "wireless"]
    }
  ,
      {
        "id": "seating_spot",
        "entity_kind": "REGION",
        "function": "Location where a person sits.",
        "required_count": 2,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["chair", "seat"]
    ,
      "required_properties": ["supports_human", "facing_tv"]
    }
  ]
  ,
    "functional_relations": [
      {
        "id": "near_person",
        "relation": "is_near",
        "participant_roles": ["refreshment_setting", "seating_spot"]
      ,
        "required": true
      }
  ,
      {
        "id": "accessible_to_both",
        "relation": "is_accessible_to",
        "participant_roles": ["entertainment_control", "seating_spot"]
      ,
        "required": true
      }
    ]
  ,
    "operation_pairings": [
      {
        "id": "prepare_refreshments",
        "operation": "place_items_on",
        "participant_roles": ["refreshment_setting", "refreshment_item"]
      ,
        "operation_count": 2
      }
  ,
      {
        "id": "move_control",
        "operation": "move_to",
        "participant_roles": ["entertainment_control", "seating_spot"]
      ,
        "operation_count": 1
      }
    ]
  }
  ,
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "coffee_table", "visual_description": "Central low table with a cup on it"},
        {"label": "desk", "visual_description": "Large wooden desk with plates and a remote"},
        {"label": "side_tables", "visual_description": "Small tables next to chairs"}
      ],
      "entertainment_control": [
        {"label": "remote", "visual_description": "Black rectangular object on the desk"}
      ],
      "seating_spot": [
        {"label": "left_chair", "visual_description": "Armchair on the left"},
        {"label": "right_chair", "visual_description": "Armchair on the right"}
      ]
    },
    "inspectable_regions": [
      {"id": "desk", "label": "desk", "visual_description": "Large wooden desk with potential drawers", "reason": "May contain additional controls or supplies"},
      {"id": "console_table", "label": "console_table", "visual_description": "Long table under the TV", "reason": "May contain media equipment or supplies"}
    ],
    "inspection_order": ["desk", "console_table"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
